/* ───────── Utilitaires & Pochettes Pré-décodées en VRAM (0ms de latence) ───────── */

const POCHETTE_URLS = EMBEDDED_POCHETTES.map((dataUri) => {
  try {
    const parts = dataUri.split(",");
    const byteString = atob(parts[1]);
    const ab = new ArrayBuffer(byteString.length);
    const ia = new Uint8Array(ab);
    for (let i = 0; i < byteString.length; i++) {
      ia[i] = byteString.charCodeAt(i);
    }
    const blob = new Blob([ab], { type: "image/jpeg" });
    const blobUrl = URL.createObjectURL(blob);
    const preloadImg = new Image();
    preloadImg.src = blobUrl;
    if (preloadImg.decode) preloadImg.decode().catch(() => {});
    return blobUrl;
  } catch (_) {
    return dataUri;
  }
});

function hash(str) {
  let h = 0;
  for (let i = 0; i < str.length; i++) {
    h = ((h << 5) - h + str.charCodeAt(i)) | 0;
  }
  return Math.abs(h);
}

function getFallbackPochette(album, index) {
  const h = hash(album.album + album.artist);
  return POCHETTE_URLS[(h + index * 7) % POCHETTE_URLS.length];
}

function getCoverUrl(album, index) {
  if (album._coverUrl) return album._coverUrl;

  const fallback = getFallbackPochette(album, index);
  album._fallbackUrl = fallback;

  if (album.image && !album.image.includes(LASTFM_DEFAULT_HASH)) {
    album._coverUrl = album.image;
  } else {
    album._coverUrl = fallback;
  }
  return album._coverUrl;
}


/* ───────── Création d'un livre avec tailles TRÈS IRRÉGULIÈRES ───────── */

function createBook(album, index, options = {}) {
  const h       = hash(album.album + album.artist);
  const palette = bookPalettes[(h + index) % bookPalettes.length];
  const font    = titleFonts[h % titleFonts.length];
  const pattern = spinePatterns[(h + index) % spinePatterns.length];

  const isHorizontal = Boolean(options.horizontal);
  const isTopper     = Boolean(options.topper);
  const customTilt   = options.tilt ?? 0;
  const gapLeft      = options.gapLeft ?? 0;
  const gapRight     = options.gapRight ?? 0;
  const xShift       = options.xShift ?? 0;
  const maxShelfH    = options.maxShelfH ?? 220;

  let height, width, titleSize;

  if (isHorizontal) {
    // Livres couchés de longueurs et d'épaisseurs très dépareillées !
    const hWidths  = [156, 114, 138, 96, 146, 122, 104, 162];
    const hHeights = [34, 21, 28, 23, 32, 19, 26, 30];
    width     = options.customW ?? (hWidths[(h + index) % hWidths.length] + (h % 10));
    height    = options.customH ?? hHeights[(h + index * 3) % hHeights.length];
    titleSize = height < 23 ? 8.5 : height < 29 ? 10 : 11.5;
  } else {
    // Vraie irrégularité de hauteur :
    // alterne entre très grands beaux-livres (1.03), moyens (0.80) et petits carnets bas (0.58 - 0.65) !
    const heightProfile = [
      1.02, 0.64, 0.88, 0.96, 0.58, 0.82, 1.04, 0.71,
      0.91, 0.62, 0.99, 0.76, 0.67, 0.94, 0.60, 0.85,
    ];
    const ratio = options.customRatio ?? heightProfile[(h + index * 5) % heightProfile.length];
    height      = Math.max(92, Math.round(maxShelfH * ratio));

    // Vraie irrégularité d'épaisseur :
    // plaquettes très fines (23-28px), romans fins (31-38px), beaux-livres (42-50px), gros tome (54-62px)
    const widthProfile = [
      34, 24, 48, 31, 58, 26, 38, 29,
      44, 23, 52, 33, 27, 41, 60, 30,
    ];
    width     = widthProfile[(h + index * 3) % widthProfile.length] + (h % 5);
    titleSize = width < 29 ? 8 : width < 37 ? 9.5 : width < 47 ? 11 : 13;
  }

  const spineRatio = width < 32 ? 60 : width < 44 ? 54 : 48;
  const faceRatio  = 100 - spineRatio;

  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = isTopper
    ? "book book--horizontal book--topper"
    : isHorizontal
    ? "book book--horizontal"
    : "book";
  btn.dataset.index = index;
  btn.setAttribute("aria-label", `${album.album} - ${album.artist}`);

  btn.style.cssText = `
    --bw: ${width}px;
    --bh: ${height}px;
    --bc: ${palette.bg};
    --text-color: ${palette.text};
    --band-color: ${palette.band};
    --spine-w: ${spineRatio}%;
    --face-w: ${faceRatio}%;
    --title-font: ${font};
    --title-size: ${titleSize}px;
    --tilt: ${customTilt}deg;
    --gap-left: ${gapLeft}px;
    --gap-right: ${gapRight}px;
    --x-shift: ${xShift}px;
    ${options.topperBottom ? `--topper-bottom: ${options.topperBottom}px;` : ""}
  `;

  const cursor = document.createElement("span");
  cursor.className = "book-cursor";
  cursor.innerHTML = `
    <span class="book-cursor-tag">ENTR\u00C9E</span>
    <span class="book-cursor-arrow"></span>
  `;

  const topPages = document.createElement("span");
  topPages.className = "book-top-pages";

  const face = document.createElement("span");
  face.className = "book-face";
  const img = document.createElement("img");
  img.alt = "";
  img.decoding = "async";
  img.src = getCoverUrl(album, index);
  img.onerror = () => {
    img.onerror = null;
    img.src = album._fallbackUrl;
    album._coverUrl = album._fallbackUrl;
  };
  face.appendChild(img);

  const spine = document.createElement("span");
  spine.className = "book-spine";
  spine.dataset.pattern = pattern;

  const code = document.createElement("span");
  code.className = "book-code";
  code.textContent = String(index + 1).padStart(2, "0");

  const titleWrap = document.createElement("span");
  titleWrap.className = "book-title-wrap";

  const title = document.createElement("span");
  title.className = "book-title";
  title.textContent = album.album;
  titleWrap.appendChild(title);

  const artist = document.createElement("span");
  artist.className = "book-artist";
  artist.textContent = album.artist;

  spine.append(code, titleWrap, artist);
  btn.append(cursor, topPages, face, spine);

  btn.addEventListener("click", () => {
    selectBook(index);
    openAlbumPoster(index);
  });

  return { btn, height, width };
}


/* ───────── Peupler une étagère avec des livres de tailles très irrégulières ───────── */

function populateMessyShelf(shelfEl, slice, startGlobalIdx, config) {
  const rowIndices = [];
  let globalIdx = startGlobalIdx;
  const { maxShelfH, stackAt, stackSize = 4, stack2At, stack2Size = 3, topperAt, dividerAt } = config;

  let i = 0;
  while (i < slice.length) {
    if (dividerAt && i === dividerAt) {
      const div = document.createElement("span");
      div.className = "shelf-divider";
      div.setAttribute("aria-hidden", "true");
      shelfEl.appendChild(div);
    }

    // 1) Piles de livres couchés décalés (plus de désordre naturel sans chevauchement)
    const isStack1 = stackAt !== undefined && i === stackAt;
    const isStack2 = stack2At !== undefined && i === stack2At;
    const currentStackSize = isStack1 ? stackSize : stack2Size;

    if ((isStack1 || isStack2) && slice.length - i >= currentStackSize + 1) {
      const stackEl = document.createElement("div");
      stackEl.className = "book-stack";

      // Largeurs dépareillées, vrais décalages latéraux et légers angles sur le haut de la pile
      const stackWidths  = [146, 120, 134, 108, 116];
      const stackHeights = [31, 22, 28, 20, 25];
      const shifts       = [0, -9, 8, -7, 6];
      const stackTilts   = [0, -0.6, 0.8, -1.1, 1.3];

      for (let k = 0; k < currentStackSize; k++) {
        const alb = slice[i + k];
        const h   = hash(alb.album + alb.artist);
        const { btn } = createBook(alb, globalIdx, {
          horizontal: true,
          customW: stackWidths[k % stackWidths.length] - (h % 10),
          customH: stackHeights[(k + h) % stackHeights.length],
          xShift: shifts[k % shifts.length] + ((h % 3) - 1) * 2,
          tilt: stackTilts[k % stackTilts.length],
          maxShelfH,
        });
        stackEl.appendChild(btn);
        allBooks.push(btn);
        rowIndices.push(globalIdx);
        globalIdx++;
      }

      shelfEl.appendChild(stackEl);
      i += currentStackSize;
      continue;
    }

    // 2) Groupe de 3 livres debout décalés + 1 livre jeté à plat par-dessus
    if (topperAt !== undefined && i === topperAt && slice.length - i >= 4) {
      const clusterEl = document.createElement("div");
      clusterEl.className = "book-cluster";
      const rowEl = document.createElement("div");
      rowEl.className = "book-cluster-row";

      const groupRatios = [0.62, 0.73, 0.66];
      let maxHeightInGroup = 0;
      let groupTotalW = 0;

      for (let k = 0; k < 3; k++) {
        const alb = slice[i + k];
        const { btn, height, width } = createBook(alb, globalIdx, {
          tilt: k === 0 ? 0.6 : k === 2 ? -0.6 : 0,
          maxShelfH,
          customRatio: groupRatios[k],
        });
        if (height > maxHeightInGroup) maxHeightInGroup = height;
        groupTotalW += width + 1;
        rowEl.appendChild(btn);
        allBooks.push(btn);
        rowIndices.push(globalIdx);
        globalIdx++;
      }

      const topperAlb = slice[i + 3];
      const topH = hash(topperAlb.album + topperAlb.artist);
      const { btn: topperBtn } = createBook(topperAlb, globalIdx, {
        horizontal: true,
        topper: true,
        customW: Math.max(82, groupTotalW - 2),
        customH: 23,
        xShift: (topH % 2 === 0) ? -4 : 4,
        tilt: (topH % 2 === 0) ? -2.3 : 2.1,
        topperBottom: maxHeightInGroup + 2,
        maxShelfH,
      });

      clusterEl.append(rowEl, topperBtn);
      allBooks.push(topperBtn);
      rowIndices.push(globalIdx);
      globalIdx++;

      shelfEl.appendChild(clusterEl);
      i += 4;
      continue;
    }

    // 3) Livres debout & paires "domino" penchées dans le même sens (vrai désordre sans croisement)
    const album = slice[i];
    const isNextObstacle =
      i >= slice.length - 1 ||
      i + 1 === stackAt ||
      i + 1 === stack2At ||
      i + 1 === topperAt ||
      i + 1 === dividerAt;
    const isPrevObstacle =
      i === 0 ||
      i === dividerAt ||
      (stackAt !== undefined && i === stackAt + stackSize) ||
      (stack2At !== undefined && i === stack2At + stack2Size) ||
      (topperAt !== undefined && i === topperAt + 4);

    const patternIdx = (i + startGlobalIdx * 3) % 9;

    let tilt = 0;
    let gapLeft = 1;
    let gapRight = 1;

    if (!isNextObstacle && !isPrevObstacle) {
      if (patternIdx === 1) {
        // Premier livre d'un duo penché vers la droite (s'appuie sur son voisin)
        tilt = 5.8;
        gapLeft = 3;
        gapRight = 3;
      } else if (patternIdx === 2) {
        // Second livre du duo penché vers la droite + espace de dégagement à droite
        tilt = 4.6;
        gapLeft = 1;
        gapRight = 16;
      } else if (patternIdx === 4) {
        // Livre penché vers la gauche avec dégagement à gauche
        tilt = -5.2;
        gapLeft = 16;
        gapRight = 2;
      } else if (patternIdx === 5) {
        // Second livre penché en parallèle vers la gauche (s'appuie sur le précédent)
        tilt = -4.2;
        gapLeft = 2;
        gapRight = 3;
      } else if (patternIdx === 7) {
        // Livre isolé légèrement de travers
        tilt = 3.8;
        gapLeft = 2;
        gapRight = 13;
      } else if (patternIdx === 8) {
        tilt = -3.4;
        gapLeft = 12;
        gapRight = 2;
      }
    } else if (!isNextObstacle && isPrevObstacle && i > 0) {
      // Juste après un obstacle : peut pencher légèrement vers la droite
      tilt = 3.2;
      gapLeft = 3;
      gapRight = 11;
    } else if (isNextObstacle && !isPrevObstacle && i < slice.length - 1) {
      // Juste avant une pile ou un séparateur : peut s'appuyer légèrement vers la droite
      tilt = 2.4;
      gapLeft = 2;
      gapRight = 9;
    }

    const { btn } = createBook(album, globalIdx, {
      tilt,
      gapLeft,
      gapRight,
      maxShelfH,
    });
    shelfEl.appendChild(btn);
    allBooks.push(btn);
    rowIndices.push(globalIdx);
    globalIdx++;
    i++;
  }

  return { rowIndices, nextGlobalIdx: globalIdx };
}


/* ───────── Formatage de la date de dernière écoute Last.fm (sans inventer de date) ───────── */

function formatLastListened(album) {
  if (album.last_listened_uts) {
    const date = new Date(album.last_listened_uts * 1000);
    const formatted = date.toLocaleDateString("fr-FR", {
      day: "numeric",
      month: "short",
      year: "numeric",
    });

    const diffSec  = Math.max(0, Math.floor(Date.now() / 1000) - album.last_listened_uts);
    const diffDays = Math.floor(diffSec / 86400);
    const diffHours = Math.floor(diffSec / 3600);

    let relative = "";
    if (diffDays > 0) {
      relative = `il y a ${diffDays} jour${diffDays > 1 ? "s" : ""}`;
    } else if (diffHours > 0) {
      relative = `il y a ${diffHours} h`;
    } else {
      relative = "aujourd'hui";
    }

    return {
      badge: relative.toUpperCase(),
      line: `Derni\u00E8re \u00E9coute : ${formatted}`,
    };
  }

  if (album.last_listened_date) {
    return {
      badge: "ARCHIVE LAST.FM",
      line: `Derni\u00E8re \u00E9coute : ${album.last_listened_date}`,
    };
  }

  return {
    badge: "10% PLUS ANCIENS",
    line: "Ancienne \u00E9coute Last.fm",
  };
}


/* ───────── Création du Tiroir en Bois Vintage (Étage du bas de la section droite) ───────── */

function createForgottenDrawerSlot(drawerGlobalIdx) {
  const shelfEl = document.createElement("div");
  shelfEl.className = "shelf shelf--drawer-slot";

  const drawerBtn = document.createElement("button");
  drawerBtn.type = "button";
  drawerBtn.className = "vintage-drawer-front";
  drawerBtn.dataset.index = drawerGlobalIdx;
  drawerBtn.dataset.isDrawer = "true";

  const count = forgottenAlbums.length;
  drawerBtn.setAttribute("aria-label", `Tiroir des albums oubli\u00E9s (${count})`);

  drawerBtn.innerHTML = `
    <span class="book-cursor">
      <span class="book-cursor-tag">ENTR\u00C9E</span>
      <span class="book-cursor-arrow"></span>
    </span>

    <!-- Parois internes en bois qui apparaissent quand le tiroir coulisse -->
    <div class="drawer-slide-box" aria-hidden="true">
      <div class="drawer-inner-divider"></div>
    </div>

    <!-- Façade en bois massif patiné avec porte-étiquette/tirette en métal vieilli -->
    <div class="drawer-wood-plank">
      <div class="metal-card-pull" aria-hidden="true">
        <div class="metal-frame-window"></div>
        <div class="metal-pull-lip"></div>
      </div>
    </div>
  `;

  drawerBtn.addEventListener("click", () => {
    selectBook(drawerGlobalIdx);
    triggerDrawerOpenAnimation(drawerBtn);
  });

  shelfEl.appendChild(drawerBtn);
  return { shelfEl, drawerBtn };
}

let isDrawerAnimating = false;

function triggerDrawerOpenAnimation(drawerBtn) {
  if (isDrawerAnimating) return;
  isDrawerAnimating = true;

  if (drawerBtn) {
    drawerBtn.classList.remove("drawer-pulling");
    drawerBtn.classList.add("drawer-pulling");
  }

  // Enchaînement fluide pendant que le tiroir coulisse vers l'avant (sans temps mort)
  requestAnimationFrame(() => {
    setTimeout(() => {
      openForgottenDrawer();
      isDrawerAnimating = false;
      if (drawerBtn) {
        setTimeout(() => drawerBtn.classList.remove("drawer-pulling"), 260);
      }
    }, 75);
  });
}


/* ───────── Palettes de Vieux Livres Vieillis (tons chauds : marron, noir et blanc crème) ───────── */

const agedBookPalettes = [
  { bg: "#5c361c", text: "#f2e5cc", band: "#1e120a" }, // Cuir havane chaud
  { bg: "#e8dac0", text: "#1e150e", band: "#5c361c" }, // Blanc crème parchemin & brun
  { bg: "#1e1814", text: "#ebd9b8", band: "#8c5228" }, // Noir charbon & cuir ambré
  { bg: "#7a4924", text: "#f5ead4", band: "#1e150e" }, // Marron tabac chaud
  { bg: "#3b2313", text: "#ebd9b8", band: "#b88244" }, // Brun expresso profond
  { bg: "#d9c6a3", text: "#1e150e", band: "#3b2313" }, // Papier ivoire ancien & encre noire
  { bg: "#63321c", text: "#f2e5cc", band: "#d9c6a3" }, // Acajou patiné
  { bg: "#291d16", text: "#f0e2c6", band: "#7a4924" }, // Noir sépia & marron glacé
];

let drawerBooks       = [];
let drawerCursorIndex = 0;

function createAgedDrawerBook(album, idx, options = {}) {
  const h       = hash(album.album + album.artist);
  const palette = agedBookPalettes[(h + idx) % agedBookPalettes.length];
  const font    = titleFonts[h % titleFonts.length];
  const pattern = spinePatterns[(h + idx) % spinePatterns.length];

  const isHorizontal = Boolean(options.horizontal);

  // Hauteurs, épaisseurs et inclinaisons franchement irrégulières (avec marges de dégagement anti-chevauchement)
  const heights = [234, 162, 218, 152, 226, 174, 206, 166];
  const widths  = [62, 42, 66, 44, 54, 40, 60, 48];

  const height = isHorizontal ? (options.customH ?? 34) : heights[(h + idx) % heights.length];
  const width  = isHorizontal ? (options.customW ?? 148) : widths[(h + idx * 3) % widths.length];
  const tilt   = options.tilt ?? 0;
  const gapLeft  = options.gapLeft ?? 0;
  const gapRight = options.gapRight ?? 0;
  const xShift   = options.xShift ?? 0;

  const spineRatio = isHorizontal ? 62 : 58;
  const faceRatio  = 100 - spineRatio;
  const titleSize  = isHorizontal ? 10.5 : (width < 46 ? 10.5 : width < 58 ? 12 : 13.5);

  const dateInfo = formatLastListened(album);
  const shortDate = album.last_listened_uts
    ? new Date(album.last_listened_uts * 1000).toLocaleDateString("fr-FR", { day: "2-digit", month: "short", year: "2-digit" })
    : "ANCIEN";

  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = isHorizontal ? "book book--horizontal aged-book" : "book aged-book";
  btn.dataset.drawerIdx = idx;
  btn.setAttribute("aria-label", `${album.album} - ${album.artist} (${dateInfo.line})`);

  btn.style.cssText = `
    --bw: ${width}px;
    --bh: ${height}px;
    --bc: ${palette.bg};
    --text-color: ${palette.text};
    --band-color: ${palette.band};
    --spine-w: ${spineRatio}%;
    --face-w: ${faceRatio}%;
    --title-font: ${font};
    --title-size: ${titleSize}px;
    --tilt: ${tilt}deg;
    --gap-left: ${gapLeft}px;
    --gap-right: ${gapRight}px;
    --x-shift: ${xShift}px;
    --book-delay: ${Math.min(idx * 22, 160)}ms;
  `;

  // 1. Curseur flèche rétro au-dessus du vieux livre sélectionné
  const cursor = document.createElement("span");
  cursor.className = "book-cursor";
  cursor.innerHTML = `
    <span class="book-cursor-tag">ENTR\u00C9E</span>
    <span class="book-cursor-arrow"></span>
  `;

  // 2. Pages jaunies sur le dessus
  const topPages = document.createElement("span");
  topPages.className = "book-top-pages aged-top-pages";

  // 3. Face avant (pochette d'album vieillie au sépia)
  const face = document.createElement("span");
  face.className = "book-face aged-book-face";
  const img = document.createElement("img");
  img.alt = "";
  img.src = getCoverUrl(album, 200 + idx);
  img.onerror = () => {
    img.onerror = null;
    img.src = album._fallbackUrl;
  };
  face.appendChild(img);

  // 4. Face latérale / Tranche vieillie avec le titre, l'artiste et la date d'écoute
  const spine = document.createElement("span");
  spine.className = "book-spine aged-book-spine";
  spine.dataset.pattern = pattern;

  const dateStamp = document.createElement("span");
  dateStamp.className = "aged-book-date";
  dateStamp.textContent = shortDate;

  const titleWrap = document.createElement("span");
  titleWrap.className = "book-title-wrap";

  const title = document.createElement("span");
  title.className = "book-title";
  title.textContent = album.album;
  titleWrap.appendChild(title);

  const artist = document.createElement("span");
  artist.className = "book-artist";
  artist.textContent = album.artist;

  spine.append(dateStamp, titleWrap, artist);
  btn.append(cursor, topPages, face, spine);

  btn.addEventListener("mouseenter", () => {
    selectDrawerBook(idx);
  });

  btn.addEventListener("click", () => {
    selectDrawerBook(idx);
    openAlbumPosterForAlbum(album, 200 + idx, `TIROIR \u00B7 ${dateInfo.line.toUpperCase()}`, btn);
  });

  return btn;
}

function selectDrawerBook(idx) {
  if (!drawerBooks.length) return;
  const clamped = Math.max(0, Math.min(idx, drawerBooks.length - 1));
  if (drawerBooks[drawerCursorIndex]) {
    drawerBooks[drawerCursorIndex].classList.remove("selected");
  }
  drawerCursorIndex = clamped;
  if (drawerBooks[drawerCursorIndex]) {
    drawerBooks[drawerCursorIndex].classList.add("selected");
  }
}

function prepareForgottenDrawerDOM() {
  drawerGrid.replaceChildren();
  drawerBooks = [];
  drawerCursorIndex = 0;

  // Appliquer la même DA que la page Poster d'album (avec l'affiche sépia pochette14)
  const theme = posterThemes[13] || posterThemes[0];
  const bgArt = POCHETTE_URLS[theme.pochetteIdx];

  drawerOverlay.style.setProperty("--stage-bg", theme.stage);
  drawerOverlay.style.setProperty("--poster-art", `url("${bgArt}")`);

  const drawerCard = document.getElementById("drawer-card");
  if (drawerCard) {
    drawerCard.style.setProperty("--poster-bg", theme.bg);
    drawerCard.style.setProperty("--poster-panel", theme.panel);
    drawerCard.style.setProperty("--poster-veil", theme.veil);
    drawerCard.style.setProperty("--poster-art", `url("${bgArt}")`);
    drawerCard.style.setProperty("--poster-ink", theme.ink);
    drawerCard.style.setProperty("--poster-accent", theme.accent);
    drawerCard.style.setProperty("--poster-font", theme.font);
  }

  const count = forgottenAlbums.length;
  drawerCountBadge.textContent = `${count} ALBUM${count > 1 ? "S" : ""} OUBLI\u00C9${count > 1 ? "S" : ""} \u00B7 10% PLUS ANCIENS`;

  if (!count) {
    drawerGrid.innerHTML = '<p class="status">Aucun album oubli\u00E9 pour le moment.</p>';
  } else {
    const frag = document.createDocumentFragment();

    // Configurations d'inclinaison variées dans le tiroir (duos penchés et livres en vrac sans chevauchement)
    const drawerPostures = [
      { tilt: -5.8, gapLeft: 16, gapRight: 2 },
      { tilt: -4.2, gapLeft: 1,  gapRight: 6 },
      { tilt: 0.8,  gapLeft: 2,  gapRight: 4 },
      { tilt: 5.4,  gapLeft: 2,  gapRight: 3 },
      { tilt: 4.4,  gapLeft: 1,  gapRight: 16 },
      { tilt: -3.6, gapLeft: 12, gapRight: 2 },
      { tilt: 2.8,  gapLeft: 2,  gapRight: 10 },
      { tilt: -4.8, gapLeft: 14, gapRight: 3 },
    ];

    const stackStartIdx = count >= 5 ? 2 : -1;
    let idx = 0;

    while (idx < count) {
      // Si au moins 5 vieux albums dans le tiroir : une petite pile de 2 vieux livres posés à plat au milieu !
      if (idx === stackStartIdx && count - idx >= 2) {
        const stackEl = document.createElement("div");
        stackEl.className = "book-stack drawer-aged-stack";

        const stackConfigs = [
          { customW: 148, customH: 34, xShift: 0,  tilt: 0 },
          { customW: 128, customH: 29, xShift: -7, tilt: -1.6 },
        ];

        for (let k = 0; k < 2; k++) {
          const alb = forgottenAlbums[idx + k];
          const bookEl = createAgedDrawerBook(alb, idx + k, {
            horizontal: true,
            ...stackConfigs[k],
          });
          drawerBooks.push(bookEl);
          stackEl.appendChild(bookEl);
        }

        frag.appendChild(stackEl);
        idx += 2;
        continue;
      }

      const posture = drawerPostures[idx % drawerPostures.length];
      const bookEl  = createAgedDrawerBook(forgottenAlbums[idx], idx, posture);
      drawerBooks.push(bookEl);
      frag.appendChild(bookEl);
      idx++;
    }

    drawerGrid.appendChild(frag);
    selectDrawerBook(0);
  }
}

function openForgottenDrawer() {
  if (!drawerBooks.length && forgottenAlbums.length) {
    prepareForgottenDrawerDOM();
  } else if (drawerBooks.length) {
    selectDrawerBook(drawerCursorIndex);
  }
  drawerOverlay.classList.remove("is-closing");
  drawerOverlay.hidden = false;
}

function closeForgottenDrawer() {
  if (drawerOverlay.hidden || drawerOverlay.classList.contains("is-closing")) return;
  drawerOverlay.classList.add("is-closing");
  setTimeout(() => {
    drawerOverlay.hidden = true;
    drawerOverlay.classList.remove("is-closing");
  }, 170);
}

closeDrawerBtn.addEventListener("click", closeForgottenDrawer);

drawerOverlay.addEventListener("click", (e) => {
  if (e.target === drawerOverlay || e.target.classList.contains("poster-stage")) {
    closeForgottenDrawer();
  }
});


/* ───────── Rendu Global : 2 Grandes Étagères à Gauche + 2 Étages + Tiroir à Droite ───────── */

function renderLibrary(albums) {
  shelvesEl.replaceChildren();
  allBooks = [];
  shelfMatrix = [];

  if (!albums.length && !forgottenAlbums.length) {
    shelvesEl.innerHTML = '<p class="status">Aucun album trouv\u00E9 dans ton historique Last.fm.</p>';
    return;
  }

  const vh = window.innerHeight - 54;

  const visible = albums.slice(0, 62);
  const total   = visible.length;

  // Répartition sur les 4 étagères à livres (2 grandes à gauche + 2 étroites en haut à droite),
  // le 3e étage en bas à droite étant réservé au Tiroir des Albums Oubliés !
  const weights = [0.36, 0.36, 0.14, 0.14];

  const slices = [];
  let cursor = 0;
  weights.forEach((w, idx) => {
    const count = idx === weights.length - 1
      ? total - cursor
      : Math.max(1, Math.round(total * w));
    slices.push(visible.slice(cursor, cursor + count));
    cursor += count;
  });

  const mainCol  = document.createElement("div");
  mainCol.className = "bookcase-main";

  const towerCol = document.createElement("div");
  towerCol.className = "bookcase-tower";

  let globalIdx = 0;

  const mainBookMaxH  = Math.max(170, Math.floor(vh * 0.38));
  const towerBookMaxH = Math.max(145, Math.floor(vh / 3) - 12);

  const mainConfigs = [
    {
      maxShelfH: mainBookMaxH,
      stackAt: Math.max(2, Math.floor(slices[0].length * 0.20)),
      stackSize: 5,
      stack2At: slices[0].length >= 15 ? Math.floor(slices[0].length * 0.68) : undefined,
      stack2Size: 3,
      topperAt: Math.max(6, Math.floor(slices[0].length * 0.44)),
      dividerAt: Math.max(5, Math.floor(slices[0].length * 0.40)),
    },
    {
      maxShelfH: mainBookMaxH,
      stackAt: Math.max(3, Math.floor(slices[1].length * 0.34)),
      stackSize: 4,
      stack2At: slices[1].length >= 16 ? Math.floor(slices[1].length * 0.76) : undefined,
      stack2Size: 5,
      topperAt: 1,
      dividerAt: Math.max(4, Math.floor(slices[1].length * 0.58)),
    },
  ];

  const mainRows = [];
  for (let s = 0; s < 2; s++) {
    const shelfEl = document.createElement("div");
    shelfEl.className = "shelf";
    const res = populateMessyShelf(shelfEl, slices[s], globalIdx, mainConfigs[s]);
    globalIdx = res.nextGlobalIdx;
    mainRows.push(res.rowIndices);
    mainCol.appendChild(shelfEl);
  }

  // Les 2 premiers étages de la section de droite : livres
  const towerRows = [];
  for (let t = 0; t < 2; t++) {
    const shelfEl = document.createElement("div");
    shelfEl.className = "shelf";
    const slice = slices[2 + t];
    const res = populateMessyShelf(shelfEl, slice, globalIdx, {
      maxShelfH: towerBookMaxH,
      stackAt: slice.length >= 6 ? (t % 2 === 0 ? 2 : 3) : undefined,
      stackSize: t === 0 ? 4 : 3,
      dividerAt: slice.length >= 7 ? Math.floor(slice.length * 0.55) : undefined,
    });
    globalIdx = res.nextGlobalIdx;
    towerRows.push(res.rowIndices);
    towerCol.appendChild(shelfEl);
  }

  // Le 3e étage (en bas de la section de droite) : THE FORGOTTEN ALBUMS DRAWER
  const drawerIdx = globalIdx++;
  const { shelfEl: drawerShelfEl, drawerBtn } = createForgottenDrawerSlot(drawerIdx);
  allBooks.push(drawerBtn);
  towerRows.push([drawerIdx]);
  towerCol.appendChild(drawerShelfEl);

  shelfMatrix = [
    [...(mainRows[0] || []), ...(towerRows[0] || [])],
    [...(towerRows[1] || [])],
    [...(mainRows[1] || []), ...(towerRows[2] || [])],
  ].filter(r => r.length > 0);

  shelvesEl.append(mainCol, towerCol);

  const safeIndex = Math.min(cursorIndex, allBooks.length - 1);
  selectBook(Math.max(0, safeIndex));
}


/* ───────── Sélection Clavier Instantanée ───────── */

function selectBook(index) {
  if (!allBooks.length) return;
  const clamped = Math.max(0, Math.min(index, allBooks.length - 1));

  if (allBooks[cursorIndex]) {
    allBooks[cursorIndex].classList.remove("selected");
  }
  cursorIndex = clamped;

  const activeBook = allBooks[cursorIndex];
  if (activeBook) {
    activeBook.classList.add("selected");
  }
}

function moveShelfVertical(direction) {
  for (let r = 0; r < shelfMatrix.length; r++) {
    const col = shelfMatrix[r].indexOf(cursorIndex);
    if (col !== -1) {
      const targetRow = (r + direction + shelfMatrix.length) % shelfMatrix.length;
      const targetRowArr = shelfMatrix[targetRow];
      const ratio = col / Math.max(1, shelfMatrix[r].length - 1);
      const targetCol = Math.round(ratio * (targetRowArr.length - 1));
      selectBook(targetRowArr[targetCol]);
      return;
    }
  }
}


/* ───────── Animation Physique du Livre 3D (Sortie de l'étagère -> Pivot Reliure -> Intérieur) ───────── */

let pulledOutBookEl = null;
let wrapperAnim     = null;
let coverAnim       = null;
let isBookClosing   = false;
let isBookSwitching = false;
let isAlbumPageOpen = false;
let activeBookIndex = 0;

function prefersReducedMotion() {
  return window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

function getBookOriginVector(bookEl) {
  if (!bookEl) {
    return { dx: 0, dy: 48, tilt: "0deg" };
  }
  const rect = bookEl.getBoundingClientRect();
  const bookCenterX = rect.left + rect.width / 2;
  const bookCenterY = rect.top + rect.height / 2;
  const viewportCenterX = window.innerWidth / 2;
  const viewportCenterY = window.innerHeight / 2;

  return {
    dx: Math.round((bookCenterX - viewportCenterX) * 0.65),
    dy: Math.round((bookCenterY - viewportCenterY) * 0.65),
    tilt: bookEl.style.getPropertyValue("--tilt")?.trim() || "0deg",
  };
}

function cancelBookAnimations() {
  if (wrapperAnim) {
    wrapperAnim.cancel();
    wrapperAnim = null;
  }
  if (coverAnim) {
    coverAnim.cancel();
    coverAnim = null;
  }
}

function populateBookDOM(album, index, customSubtitle, sourceBookEl) {
  activePosterAlbum = album;
  activeBookIndex   = index;

  const h       = hash(album.album + album.artist);
  const theme   = posterThemes[(h + index * 7) % posterThemes.length];
  const bgArt   = POCHETTE_URLS[theme.pochetteIdx];
  const palette = index >= 200
    ? agedBookPalettes[(h + (index - 200)) % agedBookPalettes.length]
    : bookPalettes[(h + index) % bookPalettes.length];
  const bookFont = titleFonts[h % titleFonts.length];

  const wrapper = document.getElementById("book-3d-wrapper");
  if (wrapper) {
    const bc   = sourceBookEl?.style.getPropertyValue("--bc").trim() || palette.bg;
    const tc   = sourceBookEl?.style.getPropertyValue("--text-color").trim() || palette.text;
    const band = sourceBookEl?.style.getPropertyValue("--band-color").trim() || palette.band;
    wrapper.style.setProperty("--book-cover-bg", bc);
    wrapper.style.setProperty("--book-cover-text", tc);
    wrapper.style.setProperty("--book-cover-band", band);
    wrapper.style.setProperty("--book-cover-font", bookFont);
    wrapper.style.setProperty("--poster-bg", theme.bg);
    wrapper.style.setProperty("--poster-panel", theme.panel);
    wrapper.style.setProperty("--poster-veil", theme.veil);
    wrapper.style.setProperty("--poster-ink", theme.ink);
    wrapper.style.setProperty("--poster-accent", theme.accent);
    wrapper.style.setProperty("--poster-font", theme.font);
  }

  const card = document.getElementById("poster-card");
  card.style.setProperty("--poster-bg", theme.bg);
  card.style.setProperty("--poster-panel", theme.panel);
  card.style.setProperty("--poster-veil", theme.veil);
  card.style.setProperty("--poster-ink", theme.ink);
  card.style.setProperty("--poster-accent", theme.accent);
  card.style.setProperty("--poster-font", theme.font);

  const bgImg = document.getElementById("poster-bg-img");
  if (bgImg && bgImg.src !== bgArt) {
    bgImg.src = bgArt;
  }

  const coverUrl = getCoverUrl(album, index);
  const numLabel = `N\u00B0 ${String((index % 99) + 1).padStart(2, "0")}`;

  // 1) Couverture extérieure du livre fermé
  const cover3dNum    = document.getElementById("cover-3d-num");
  const cover3dImg    = document.getElementById("cover-3d-img");
  const cover3dTitle  = document.getElementById("cover-3d-title");
  const cover3dArtist = document.getElementById("cover-3d-artist");
  const cover3dDate   = document.getElementById("cover-3d-date");

  if (cover3dNum)    cover3dNum.textContent    = numLabel;
  if (cover3dTitle)  cover3dTitle.textContent  = album.album;
  if (cover3dArtist) cover3dArtist.textContent = album.artist;
  if (cover3dImg) {
    cover3dImg.onerror = () => {
      cover3dImg.onerror = null;
      cover3dImg.src = album._fallbackUrl || bgArt;
    };
    cover3dImg.src = coverUrl;
  }

  // 2) Pages intérieures du livre ouvert (Page Gauche = Pochette & Date / Page Droite = Titres)
  const cover = document.getElementById("poster-cover");
  cover.alt = "";
  cover.onerror = () => {
    cover.onerror = null;
    cover.src = album._fallbackUrl || bgArt;
  };
  cover.src = coverUrl;

  document.getElementById("poster-num").textContent    = numLabel;
  document.getElementById("poster-plays").textContent  = customSubtitle
    || (album.plays ? `${album.plays} \u00C9COUTE${album.plays > 1 ? "S" : ""} LAST.FM` : "COLLECTION");
  document.getElementById("poster-artist").textContent  = album.artist;
  document.getElementById("poster-title").textContent   = album.album;
  document.getElementById("poster-sticker").textContent = theme.sticker;

  // Date de dernière écoute (si fournie par Last.fm)
  const lastListenedEl = document.getElementById("poster-last-listened");
  if (album.last_listened_uts || album.last_listened_date) {
    const dateInfo = formatLastListened(album);
    if (lastListenedEl) {
      lastListenedEl.textContent = `${dateInfo.line} (${dateInfo.badge.toLowerCase()})`;
      lastListenedEl.hidden = false;
    }
    if (cover3dDate) cover3dDate.textContent = dateInfo.badge;
  } else {
    if (lastListenedEl) lastListenedEl.hidden = true;
    if (cover3dDate) cover3dDate.textContent = "COLLECTION VINYLE";
  }

  const count = album.tracks.length;
  document.getElementById("poster-track-count").textContent =
    `${count} TITRE${count > 1 ? "S" : ""} \u00C9COUT\u00C9${count > 1 ? "S" : ""}`;

  const list = document.getElementById("poster-tracks");
  list.replaceChildren();

  album.tracks.forEach(trackName => {
    const li = document.createElement("li");
    li.textContent = trackName;
    list.appendChild(li);
  });
}

/* Animation Web Animations API 100% GPU : Sortie de l'étagère (livre fermé) -> Centre -> Ouverture -180° en double page */
function playBookOpenAnimation(sourceBookEl, onComplete) {
  const wrapper = document.getElementById("book-3d-wrapper");
  const cover   = document.getElementById("book-3d-cover");
  if (!wrapper || !cover) return;

  cancelBookAnimations();
  const { dx, dy, tilt } = getBookOriginVector(sourceBookEl);

  if (prefersReducedMotion() || !wrapper.animate) {
    wrapper.style.transform = "translate3d(50%, 0px, 0) scale(1) rotate(-0.3deg)";
    wrapper.style.opacity   = "1";
    cover.style.transform   = "rotateY(-180deg)";
    if (onComplete) onComplete();
    return;
  }

  const duration = 1150;
  const easing   = "cubic-bezier(0.38, 0.04, 0.22, 1)";

  // 1) Trajectoire du livre : part de son étagère (fermé) -> arrive au centre (35%) -> se décale à +50% à mesure que la page gauche s'ouvre
  wrapperAnim = wrapper.animate(
    [
      {
        transform: `translate3d(${dx}px, ${dy}px, 0) scale(0.42) rotate(${tilt})`,
        opacity: 0,
        offset: 0,
      },
      {
        transform: "translate3d(0%, 6px, 0) scale(0.92) rotate(0deg)",
        opacity: 1,
        offset: 0.34,
      },
      {
        transform: "translate3d(50%, 0px, 0) scale(1) rotate(-0.3deg)",
        opacity: 1,
        offset: 1,
      },
    ],
    { duration, easing, fill: "forwards" }
  );

  // 2) Pivot 3D de la couverture autour de la reliure : reste fermée (0deg) jusqu'à 30%, puis s'ouvre à -180deg pour former la page gauche !
  coverAnim = cover.animate(
    [
      { transform: "rotateY(0deg)",    offset: 0 },
      { transform: "rotateY(-4deg)",   offset: 0.30 },
      { transform: "rotateY(-180deg)", offset: 1 },
    ],
    { duration, easing, fill: "forwards" }
  );

  wrapperAnim.onfinish = () => {
    wrapper.style.transform = "translate3d(50%, 0px, 0) scale(1) rotate(-0.3deg)";
    wrapper.style.opacity   = "1";
    cover.style.transform   = "rotateY(-180deg)";
    if (onComplete) onComplete();
  };
}

/* Animation inverse 100% GPU : La page gauche se referme (0deg) sur la page droite -> Le livre fermé retourne à son étagère */
function playBookCloseAnimation(targetBookEl, onComplete) {
  const wrapper = document.getElementById("book-3d-wrapper");
  const cover   = document.getElementById("book-3d-cover");
  if (!wrapper || !cover) {
    if (onComplete) onComplete();
    return;
  }

  cancelBookAnimations();
  const { dx, dy, tilt } = getBookOriginVector(targetBookEl);

  if (prefersReducedMotion() || !wrapper.animate) {
    if (onComplete) onComplete();
    return;
  }

  const duration = 900;
  const easing   = "cubic-bezier(0.4, 0, 0.2, 1)";

  wrapperAnim = wrapper.animate(
    [
      {
        transform: "translate3d(50%, 0px, 0) scale(1) rotate(-0.3deg)",
        opacity: 1,
        offset: 0,
      },
      {
        transform: "translate3d(0%, 6px, 0) scale(0.92) rotate(0deg)",
        opacity: 1,
        offset: 0.58,
      },
      {
        transform: `translate3d(${dx}px, ${dy}px, 0) scale(0.42) rotate(${tilt})`,
        opacity: 0,
        offset: 1,
      },
    ],
    { duration, easing, fill: "forwards" }
  );

  coverAnim = cover.animate(
    [
      { transform: "rotateY(-180deg)", offset: 0 },
      { transform: "rotateY(0deg)",    offset: 0.62 },
      { transform: "rotateY(0deg)",    offset: 1 },
    ],
    { duration, easing, fill: "forwards" }
  );

  wrapperAnim.onfinish = () => {
    if (onComplete) onComplete();
  };
}

function openAlbumPoster(index) {
  const activeEl = allBooks[index];
  if (activeEl && activeEl.dataset.isDrawer === "true") {
    triggerDrawerOpenAnimation(activeEl);
    return;
  }

  const album = allAlbums[index];
  if (!album) return;
  openAlbumPosterForAlbum(album, index, null, activeEl);
}

function openAlbumPosterForAlbum(album, index = 0, customSubtitle = null, sourceBookEl = null) {
  isBookClosing   = false;
  isBookSwitching = false;

  if (pulledOutBookEl && pulledOutBookEl !== sourceBookEl) {
    pulledOutBookEl.classList.remove("book--extracting", "book--pulled-out");
  }
  pulledOutBookEl = sourceBookEl || null;
  if (pulledOutBookEl) {
    pulledOutBookEl.classList.add("book--pulled-out");
  }

  populateBookDOM(album, index, customSubtitle, sourceBookEl);

  isAlbumPageOpen = true;
  albumPage.setAttribute("aria-hidden", "false");
  albumPage.classList.remove("is-book-closing");
  albumPage.classList.add("is-book-visible", "is-book-active");

  playBookOpenAnimation(pulledOutBookEl);
}

/* Passage d'un album à un autre : le livre actuel se referme et retourne à son rayon, puis le suivant s'ouvre */
function switchBookByOffset(delta) {
  if (!isAlbumPageOpen || isBookClosing || isBookSwitching) return;

  const isDrawerBook = activeBookIndex >= 200;
  let nextAlbum, nextIdx, nextSubtitle = null, nextBookEl = null;

  if (isDrawerBook) {
    if (!forgottenAlbums.length) return;
    const currentDrawerIdx = activeBookIndex - 200;
    const targetDrawerIdx  = (currentDrawerIdx + delta + forgottenAlbums.length) % forgottenAlbums.length;
    selectDrawerBook(targetDrawerIdx);
    nextAlbum    = forgottenAlbums[targetDrawerIdx];
    nextIdx      = 200 + targetDrawerIdx;
    const dateInfo = formatLastListened(nextAlbum);
    nextSubtitle = `TIROIR \u00B7 ${dateInfo.line.toUpperCase()}`;
    nextBookEl   = drawerBooks[targetDrawerIdx] || null;
  } else {
    if (!allAlbums.length) return;
    // Ordre exact des livres dans la bibliothèque (de 0 à allAlbums.length - 1)
    const targetShelfIdx = (cursorIndex + delta + allAlbums.length) % allAlbums.length;
    selectBook(targetShelfIdx);
    nextAlbum  = allAlbums[targetShelfIdx];
    nextIdx    = targetShelfIdx;
    nextBookEl = allBooks[targetShelfIdx] || null;
  }

  if (!nextAlbum) return;

  if (prefersReducedMotion()) {
    openAlbumPosterForAlbum(nextAlbum, nextIdx, nextSubtitle, nextBookEl);
    return;
  }

  isBookSwitching = true;
  const previousBookEl = pulledOutBookEl;

  // 1) Fermer le livre actuel et le renvoyer vers sa place sur l'étagère
  playBookCloseAnimation(previousBookEl, () => {
    if (previousBookEl) {
      previousBookEl.classList.remove("book--extracting", "book--pulled-out");
    }

    // 2) Sortir le livre suivant de son propre emplacement et l'ouvrir au centre
    pulledOutBookEl = nextBookEl;
    if (pulledOutBookEl) {
      pulledOutBookEl.classList.add("book--pulled-out");
    }
    populateBookDOM(nextAlbum, nextIdx, nextSubtitle, nextBookEl);

    playBookOpenAnimation(nextBookEl, () => {
      isBookSwitching = false;
    });
  });
}

function closeAlbumPoster() {
  if (!isAlbumPageOpen || isBookClosing) return;

  isBookClosing   = true;
  isBookSwitching = false;
  const closingBookEl = pulledOutBookEl;

  albumPage.classList.remove("is-book-active");
  albumPage.classList.add("is-book-closing");

  playBookCloseAnimation(closingBookEl, () => {
    cancelBookAnimations();
    isAlbumPageOpen = false;
    isBookClosing   = false;
    albumPage.setAttribute("aria-hidden", "true");
    albumPage.classList.remove("is-book-visible", "is-book-closing");
    if (closingBookEl) {
      closingBookEl.classList.remove("book--extracting", "book--pulled-out");
    }
    pulledOutBookEl = null;
  });
}

backBtn.addEventListener("click", closeAlbumPoster);

prevBtn.addEventListener("click", () => {
  switchBookByOffset(-1);
});

nextBtn.addEventListener("click", () => {
  switchBookByOffset(1);
});

albumPage.addEventListener("click", (e) => {
  if (e.target === albumPage || e.target.classList.contains("poster-stage")) {
    closeAlbumPoster();
  }
});


/* ───────── Contrôles Clavier ───────── */

document.addEventListener("keydown", (e) => {
  if (isAlbumPageOpen) {
    if (e.key === "Escape" || e.key === "Backspace") {
      e.preventDefault();
      closeAlbumPoster();
    } else if (e.key === "ArrowRight") {
      e.preventDefault();
      switchBookByOffset(1);
    } else if (e.key === "ArrowLeft") {
      e.preventDefault();
      switchBookByOffset(-1);
    }
    return;
  }

  if (!drawerOverlay.hidden) {
    if (e.key === "Escape" || e.key === "Backspace") {
      e.preventDefault();
      closeForgottenDrawer();
    } else if (e.key === "ArrowRight" && drawerBooks.length) {
      e.preventDefault();
      selectDrawerBook((drawerCursorIndex + 1) % drawerBooks.length);
    } else if (e.key === "ArrowLeft" && drawerBooks.length) {
      e.preventDefault();
      selectDrawerBook((drawerCursorIndex - 1 + drawerBooks.length) % drawerBooks.length);
    } else if ((e.key === "Enter" || e.key === " ") && drawerBooks[drawerCursorIndex]) {
      e.preventDefault();
      drawerBooks[drawerCursorIndex].click();
    }
    return;
  }

  switch (e.key) {
    case "ArrowRight":
      e.preventDefault();
      selectBook((cursorIndex + 1) % allBooks.length);
      break;

    case "ArrowLeft":
      e.preventDefault();
      selectBook((cursorIndex - 1 + allBooks.length) % allBooks.length);
      break;

    case "ArrowDown":
      e.preventDefault();
      moveShelfVertical(1);
      break;

    case "ArrowUp":
      e.preventDefault();
      moveShelfVertical(-1);
      break;

    case "Enter":
    case " ":
      e.preventDefault();
      openAlbumPoster(cursorIndex);
      break;
  }
});


/* ───────── Chargement & Calcul des 10% d'Albums Oubliés (Live Last.fm) ───────── */

async function loadAlbums(isBackgroundRefresh = false) {
  let data;
  try {
    const res = await fetch("./albums.json");
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    data = await res.json();
  } catch (err) {
    if (!isBackgroundRefresh) {
      shelvesEl.innerHTML =
        '<p class="status">Impossible de charger la biblioth\u00E8que pour le moment.</p>';
    }
    console.error("Erreur API /api/albums :", err);
    return;
  }

  try {
    let mainList      = data.albums || [];
    let forgottenList = data.forgotten_albums;

    // Fallback automatique si le conteneur backend n'a pas encore été rebuildé :
    // séparer les 10 % d'albums les plus anciens de la liste d'écoutes Last.fm
    if (!Array.isArray(forgottenList)) {
      if (mainList.length >= 2) {
        const forgottenCount = Math.max(1, Math.round(mainList.length * 0.10));
        forgottenList = mainList.slice(-forgottenCount).reverse();
        mainList      = mainList.slice(0, mainList.length - forgottenCount);
      } else {
        forgottenList = [];
      }
    }

    const fingerprint = [
      ...mainList.map(a => `M:${a.artist}:${a.album}:${a.plays}:${a.last_listened_uts || ""}`),
      ...forgottenList.map(a => `F:${a.artist}:${a.album}:${a.plays}:${a.last_listened_uts || ""}`),
    ].join("|");

    if (fingerprint !== lastFingerprint) {
      lastFingerprint = fingerprint;
      allAlbums       = mainList;
      forgottenAlbums = forgottenList;

      if (!isAlbumPageOpen) {
        renderLibrary(allAlbums);
        prepareForgottenDrawerDOM();
      }
    }
  } catch (renderErr) {
    console.error("Erreur de rendu :", renderErr);
  }
}

let resizeTimer;
window.addEventListener("resize", () => {
  clearTimeout(resizeTimer);
  resizeTimer = setTimeout(() => {
    if (!isAlbumPageOpen && (allAlbums.length || forgottenAlbums.length)) {
      renderLibrary(allAlbums);
    }
  }, 200);
});

// Force le rafraîchissement du favicon dans l'onglet du navigateur (et recharge /image/flavicon.jpg dynamiquement s'il est servi)
(function ensureTabFavicon() {
  function applyFaviconHref(href) {
    document.querySelectorAll("link[rel*='icon']").forEach(el => el.remove());
    const fresh = document.createElement("link");
    fresh.id = "site-favicon";
    fresh.rel = "icon";
    fresh.type = "image/png";
    fresh.href = href;
    document.head.appendChild(fresh);
  }

  const existing = document.getElementById("site-favicon");
  if (existing && existing.href) {
    applyFaviconHref(existing.href);
  }

  // Si /image/flavicon.jpg est accessible via le volume Docker, on le recadre en cercle automatiquement au cas où le fichier change
  const probe = new Image();
  probe.onload = () => {
    try {
      const c = document.createElement("canvas");
      const w = probe.naturalWidth || 64;
      const h = probe.naturalHeight || 64;
      c.width = w;
      c.height = h;
      const ctx = c.getContext("2d");
      ctx.drawImage(probe, 0, 0);
      const data = ctx.getImageData(0, 0, w, h).data;
      let minX = w, minY = h, maxX = 0, maxY = 0;
      for (let y = 0; y < h; y++) {
        for (let x = 0; x < w; x++) {
          const i = (y * w + x) * 4;
          if (data[i] < 200 || data[i + 1] < 200 || data[i + 2] < 200) {
            if (x < minX) minX = x;
            if (x > maxX) maxX = x;
            if (y < minY) minY = y;
            if (y > maxY) maxY = y;
          }
        }
      }
      if (maxX > minX && maxY > minY) {
        const pad = 6;
        minX = Math.max(0, minX - pad);
        minY = Math.max(0, minY - pad);
        maxX = Math.min(w - 1, maxX + pad);
        maxY = Math.min(h - 1, maxY + pad);
        const size = Math.max(maxX - minX + 1, maxY - minY + 1);
        const cx = (minX + maxX) / 2;
        const cy = (minY + maxY) / 2;
        const out = document.createElement("canvas");
        out.width = 64;
        out.height = 64;
        const octx = out.getContext("2d");
        octx.beginPath();
        octx.arc(32, 32, 31, 0, Math.PI * 2);
        octx.closePath();
        octx.clip();
        octx.drawImage(probe, cx - size / 2, cy - size / 2, size, size, 1, 1, 62, 62);
        applyFaviconHref(out.toDataURL("image/png"));
      }
    } catch (_) {}
  };
  probe.src = `/image/flavicon.jpg?t=${Date.now()}`;
})();

loadAlbums();

setInterval(() => loadAlbums(true), 30000);
